\label{C: main theorem, same polynomial}
Let $d, \ell \in {\mathbb N}$.  There exists a positive integer $t = O_{d, \ell}(1)$ such that the following holds. Let $D\in{\mathbb N}$, let ${\textbf{v}}_0, \ldots, {\textbf{v}}_\ell\in{\mathbb Z}^{{D}}$ be nonzero vectors of size $O(1)$ (with ${\textbf{v}}_0 = \mathbf{0}$), and let $P\in{\mathbb Z}[z]$ be a degree-$d$ polynomial with leading coefficient $\beta_d$. 
    Then for all $N\in{\mathbb N}$ and $1$-bounded functions $f_0, \ldots, f_\ell:{\mathbb Z}^D\to{\mathbb C}$ supported on $[N]^D$, the bound
    \begin{align*}
            \abs{\sum_{{\textbf{x}}\in{\mathbb Z}^D}\mathbb{E}_{z\in[(N/\beta_d)^{1/d}]}
            f_0({\textbf{x}})\cdot f_1({\textbf{x}}+{\textbf{v}}_1 P(z))\cdots f_\ell({\textbf{x}}+{\textbf{v}}_\ell P(z))} \geq \delta N^D
    \end{align*}
    implies that
    \begin{align*}
        \norm{f_j}_{\{\beta_d ({\textbf{v}}_j-{\textbf{v}}_{j'})\cdot[\pm N/\beta_d]:\; j'\in[0,\ell],\; j'\neq j\}^{ t}}^{2^{\ell t}}\gg_{d, D, \ell}\delta^{O_{d, \ell}(1)}N^{D}
    \end{align*}
    for all $j\in[0,\ell]$.

\begin{align*}
            \abs{\sum_{{\textbf{x}}\in{\mathbb Z}^D}\mathbb{E}_{z\in[(N/\beta_d)^{1/d}]}
            f_0({\textbf{x}})\cdot f_1({\textbf{x}}+{\textbf{v}}_1 P(z))\cdots f_\ell({\textbf{x}}+{\textbf{v}}_\ell P(z))} \geq \delta N^D
    \end{align*}

\begin{align*}
        \norm{f_j}_{\{\beta_d ({\textbf{v}}_j-{\textbf{v}}_{j'})\cdot[\pm N/\beta_d]:\; j'\in[0,\ell],\; j'\neq j\}^{ t}}^{2^{\ell t}}\gg_{d, D, \ell}\delta^{O_{d, \ell}(1)}N^{D}
    \end{align*}

If $D=1$ and ${\textbf{v}}_j = j$, Corollary \ref{C: main theorem, same polynomial} tells us that
\begin{align*}
    \abs{\sum_{x\in{\mathbb Z}}\mathbb{E}_{z\in[(N/\beta_d)^{1/d}]} f_0(x)f_1(x+P(z))\cdots f_\ell(x+\ell P(z))}\geq \delta N
\end{align*}
