\label{L: bounding averages in vdC}
        Let $d, D, m, \ell, r, s\in{\mathbb N}$, and let ${\mathcal Q} = \{{\textbf{Q}}_1, \ldots, {\textbf{Q}}_s\}$ be a normal family of polynomials in ${\mathbb Z}^D[z,{\underline{h}}]$ of degree at most $d$. Suppose that $\deg {\textbf{Q}}_1 >1$.

        Let $\delta>0$ and $H, K, N\in{\mathbb N}$ be parameters satisfying 

        $H\leq \frac{\delta^2}{4}K$. Then for any $1$-bounded functions $f_0, \ldots, f_\ell:{\mathbb Z}^D\to{\mathbb C}$ supported on $[N]^D$ and any ${\underline{h}}\in{\mathbb Z}^s$, the lower bound
        \begin{align*}
            \abs{\sum_{{\textbf{x}}\in{\mathbb Z}^D}\mathbb{E}_{z\in[K]}
            f_0({\textbf{x}})f_1({\textbf{x}}+{\textbf{Q}}_1(z,{\underline{h}}))\cdots f_{s}({\textbf{x}}+{\textbf{Q}}_s(z,{\underline{h}}))} \geq \delta N^D
        \end{align*}
        implies that
        \begin{align*}
            \sum_{h_{r+1}}\mu_H(h_{r+1})\sum_{{\textbf{x}}\in{\mathbb Z}^D}\mathbb{E}_{z\in[K]}\prod_{{\textbf{Q}}\in\partial_m{\mathcal Q}}f_{{\textbf{Q}}}({\textbf{x}}+{\textbf{Q}}(z,{\underline{h}}, h_{r+1}))\geq \frac{\delta^2}{4}N^D
        \end{align*}
        for some $1$-bounded functions $f_{\textbf{Q}}:{\mathbb Z}\to{\mathbb C}$ with $f_{\partial_{h_{r+1}}{\textbf{Q}}_1 - {\textbf{Q}}_m} = f_1$.

\begin{align*}
            \abs{\sum_{{\textbf{x}}\in{\mathbb Z}^D}\mathbb{E}_{z\in[K]}
            f_0({\textbf{x}})f_1({\textbf{x}}+{\textbf{Q}}_1(z,{\underline{h}}))\cdots f_{s}({\textbf{x}}+{\textbf{Q}}_s(z,{\underline{h}}))} \geq \delta N^D
        \end{align*}

\begin{align*}
            \sum_{h_{r+1}}\mu_H(h_{r+1})\sum_{{\textbf{x}}\in{\mathbb Z}^D}\mathbb{E}_{z\in[K]}\prod_{{\textbf{Q}}\in\partial_m{\mathcal Q}}f_{{\textbf{Q}}}({\textbf{x}}+{\textbf{Q}}(z,{\underline{h}}, h_{r+1}))\geq \frac{\delta^2}{4}N^D
        \end{align*}

First, we make the important observation that all the polynomials
\begin{align}\label{E: polys after vdC}
    \sigma_{h_{r+1}}{{\textbf{Q}}}_2-{{\textbf{Q}}}_m, \ldots, \sigma_{h_{r+1}}{{\textbf{Q}}}_s - {{\textbf{Q}}}_m, {{\textbf{Q}}}_1-{{\textbf{Q}}}_m, \ldots,  {{\textbf{Q}}}_s-{{\textbf{Q}}}_m
\end{align}
are distinct from $\sigma_{h_{r+1}}{{\textbf{Q}}}_1-{{\textbf{Q}}}_m$ since all of the polynomials in ${\mathcal Q}$ are distinct from ${\textbf{Q}}_1$. In making this deduction, we crucially use the assumption that ${\textbf{Q}}_1$ is nonlinear in $z$, since otherwise ${{\textbf{Q}}}_1-{{\textbf{Q}}}_m$ and $\sigma_{h_{r+1}}{{\textbf{Q}}}_1-{{\textbf{Q}}}_m$ would be the same (note that the $\sigma$ operation removes terms independent of $z$, so were ${{\textbf{Q}}}_1$ linear, it would remove entirely the shift by $h_{r+1}$).  Consequently, when we apply the $*$ operation, we do not delete any polynomial from \eqref{E: polys after vdC} on account of its agreeing with $\sigma_{h_{r+1}}{{\textbf{Q}}}_1-{{\textbf{Q}}}_m$. The conclusion of the lemma then follows from an application of the Cauchy--Schwarz and van der Corput Inequalities, together with the change of variables ${\textbf{x}}\mapsto {\textbf{x}} -{{\textbf{Q}}}_m(z)-{\textbf{Q}}_1(h_{r+1}, {\underline{h}})$,  
which ensures that $f_{\partial_{h_{r+1}}{{\textbf{Q}}}_1 - {{\textbf{Q}}}_m} = f_1$.

\begin{align}\label{E: polys after vdC}
            \sigma_{h_{r+1}}{{\textbf{Q}}}_2-{{\textbf{Q}}}_m, \ldots, \sigma_{h_{r+1}}{{\textbf{Q}}}_s - {{\textbf{Q}}}_m, {{\textbf{Q}}}_1-{{\textbf{Q}}}_m, \ldots,  {{\textbf{Q}}}_s-{{\textbf{Q}}}_m
        \end{align}

\label{L: linear averages}
    Let $\ell, D\in{\mathbb N}$, and let ${\boldsymbol{\alpha}}_{1}, \ldots, {\boldsymbol{\alpha}}_\ell\in{\mathbb Z}^D$ be nonzero vectors with ${\boldsymbol{\alpha}}_0 = \mathbf{0}$. Let $\delta>0$ and $K, M, N\in{\mathbb N}$ be parameters with $M\ll_\ell \delta^{O_\ell(1)} K$.  Then for any $1$-bounded functions $f_0, \ldots, f_\ell:{\mathbb Z}^D\to{\mathbb C}$ supported on $[N]^D$, the lower bound
    \begin{align*}
        \abs{\sum_{{\textbf{x}}\in{\mathbb Z}^D}\mathbb{E}_{z\in[K]}f_0({\textbf{x}})\cdot \prod_{j\in[\ell]}f_j({\textbf{x}}+{\boldsymbol{\alpha}}_j z)}\geq \delta N^D
    \end{align*}
    implies that
    \begin{align*}
        \mathbb{E}_{{\underline{m}},{\underline{m}}\in[\pm M]^\ell}\sum_{{\textbf{x}}\in{\mathbb Z}^D} \Delta'_{{\boldsymbol{\alpha}}_j - {\boldsymbol{\alpha}}_0, \ldots,  {\boldsymbol{\alpha}}_j - {\boldsymbol{\alpha}}_{j-1}, {\boldsymbol{\alpha}}_j - {\boldsymbol{\alpha}}_{j+1}, \ldots, {\boldsymbol{\alpha}}_j - {\boldsymbol{\alpha}}_{\ell}; ({\underline{m}},{\underline{m}}')} f_j({\textbf{x}}) \geq \frac{\delta^{2^\ell}}{4^{2^\ell - 1}} N^D
    \end{align*}
    for each $j\in[0,\ell]$.

\begin{align*}
        \abs{\sum_{{\textbf{x}}\in{\mathbb Z}^D}\mathbb{E}_{z\in[K]}f_0({\textbf{x}})\cdot \prod_{j\in[\ell]}f_j({\textbf{x}}+{\boldsymbol{\alpha}}_j z)}\geq \delta N^D
    \end{align*}

\begin{align*}
        \mathbb{E}_{{\underline{m}},{\underline{m}}\in[\pm M]^\ell}\sum_{{\textbf{x}}\in{\mathbb Z}^D} \Delta'_{{\boldsymbol{\alpha}}_j - {\boldsymbol{\alpha}}_0, \ldots,  {\boldsymbol{\alpha}}_j - {\boldsymbol{\alpha}}_{j-1}, {\boldsymbol{\alpha}}_j - {\boldsymbol{\alpha}}_{j+1}, \ldots, {\boldsymbol{\alpha}}_j - {\boldsymbol{\alpha}}_{\ell}; ({\underline{m}},{\underline{m}}')} f_j({\textbf{x}}) \geq \frac{\delta^{2^\ell}}{4^{2^\ell - 1}} N^D
    \end{align*}

Since the hypothesis of the lemma is invariant under permutations of the functions $f_1, \ldots, f_\ell$, it suffices to consider the case $j=1$. We proceed by induction on $\ell$. Applying the Cauchy--Schwarz and van der Corput Inequalities, we get
    \begin{align*}
        \mathbb{E}_{m_1, m_1'\in[\pm M]}\sum_{{\textbf{x}}\in{\mathbb Z}^D}\mathbb{E}_{z\in[K]}\prod_{j\in[\ell]}\Delta'_{({\boldsymbol{\alpha}}_j m_1, {\boldsymbol{\alpha}}_j m_1')}f_j({\textbf{x}}+{\boldsymbol{\alpha}}_j z) \geq \frac{\delta^2}{4}N^D.
    \end{align*}
    After translating ${\textbf{x}}\mapsto{\textbf{x}}-{\boldsymbol{\alpha}}_\ell z$, we obtain the result immediately in the case $\ell = 1$, and for $\ell>1$ we invoke the case $\ell-1$ after observing that $$({\boldsymbol{\alpha}}_1 - {\boldsymbol{\alpha}}_\ell) - ({\boldsymbol{\alpha}}_j - {\boldsymbol{\alpha}}_\ell) = {\boldsymbol{\alpha}}_1 - {\boldsymbol{\alpha}}_j.$$ \qedhere

\begin{align*}
        \mathbb{E}_{m_1, m_1'\in[\pm M]}\sum_{{\textbf{x}}\in{\mathbb Z}^D}\mathbb{E}_{z\in[K]}\prod_{j\in[\ell]}\Delta'_{({\boldsymbol{\alpha}}_j m_1, {\boldsymbol{\alpha}}_j m_1')}f_j({\textbf{x}}+{\boldsymbol{\alpha}}_j z) \geq \frac{\delta^2}{4}N^D.
    \end{align*}

\begin{align}\label{E: q_j}
        {\textbf{Q}}_j(z,{\underline{h}}) = \sum_{i=1}^d {\boldsymbol{\gamma}}_{ji}({\underline{h}})z^i      
      \end{align}

\label{D: descendence}
      A {normal} family ${\mathcal Q} = ({\textbf{Q}}_1, \ldots, {\textbf{Q}}_{s})$ of polynomials in ${\mathbb Z}^D[z, {\underline{h}}]$ \textit{descends from} ${\mathcal P}$ if for each $j\in[s]$, the polynomials ${\boldsymbol{\gamma}}_{ji}$ in \eqref{E: q_j} can be expressed as\footnote{The multinomial coefficient
      \begin{align*}
          {{{u_1+\cdots + u_r+i}\choose{u_1, \ldots, u_r}}} = \frac{(u_1+\cdots+u_r+i)!}{u_1!\cdots u_r!\cdot i!}
      \end{align*}
      is the coefficient of ${\underline{h}}^{{\underline{u}}}z^i = h_1^{u_1}\cdots h_r^{u_r} z^i$ in $(z+h_1+\cdots + h_r)^{i+u_1+\cdots+u_r}$.}
          \begin{align}\label{E: gamma_ji}
              {\boldsymbol{\gamma}}_{ji}({\underline{h}}) =  \sum_{\substack{{\underline{u}}\in {\mathbb N}_0^{r},\\ |{\underline{u}}|\leq d-i}} {{{u_1+\cdots + u_r+i}\choose{u_1, \ldots, u_r}}}({\boldsymbol{\beta}}_{w_{j{\underline{u}}}(|{\underline{u}}|+i)}-{\boldsymbol{\beta}}_{w_{{\underline{u}}}(|{\underline{u}}|+i)}){\underline{h}}^{\underline{u}}
          \end{align}
        for some indices $w_{{\underline{u}}}, w_{j{\underline{u}}}\in\{0, \ldots, \ell\}$ satisfying the following properties:
      \begin{enumerate}
          \item\label{i: w_1} (Coefficients of ${\textbf{Q}}_1$) $w_{1{\underline{u}}} = 1$ for all ${\underline{u}}$.
          \item\label{i: multilinear} (Multilinearity) For each $j$, the polynomial ${\boldsymbol{\gamma}}_{1d_{1j}}-{\boldsymbol{\gamma}}_{jd_{1j}}$ (the leading coefficient of ${\textbf{Q}}_1 - {\textbf{Q}}_{j}$ as a polynomial in $z$) is multilinear in ${\underline{h}}$.  
        \item\label{i: leading coeffs} (Leading coefficients) For each $j$ and ${\underline{u}}$, the vector ${\boldsymbol{\beta}}_{1(|{\underline{u}}|+d_{1j})}-{\boldsymbol{\beta}}_{w_{j{\underline{u}}}(|{\underline{u}}|+d_{1j})}$ is nonzero only if it is the leading coefficient of  ${\textbf{P}}_1-{\textbf{P}}_{w_{j{\underline{u}}}}$.
      \end{enumerate}

\begin{align*}
          {{{u_1+\cdots + u_r+i}\choose{u_1, \ldots, u_r}}} = \frac{(u_1+\cdots+u_r+i)!}{u_1!\cdots u_r!\cdot i!}
      \end{align*}

\begin{align}\label{E: gamma_ji}
              {\boldsymbol{\gamma}}_{ji}({\underline{h}}) =  \sum_{\substack{{\underline{u}}\in {\mathbb N}_0^{r},\\ |{\underline{u}}|\leq d-i}} {{{u_1+\cdots + u_r+i}\choose{u_1, \ldots, u_r}}}({\boldsymbol{\beta}}_{w_{j{\underline{u}}}(|{\underline{u}}|+i)}-{\boldsymbol{\beta}}_{w_{{\underline{u}}}(|{\underline{u}}|+i)}){\underline{h}}^{\underline{u}}
          \end{align}

\begin{align*}
              {\boldsymbol{\gamma}}_{1d_{1j}}({\underline{h}})-{\boldsymbol{\gamma}}_{jd_{1j}}({\underline{h}}) = \sum_{\substack{{\underline{u}}\in \{0,1\}^r,\\ |{\underline{u}}|\leq d-d_{1j}}} \frac{(|{\underline{u}}|+d_{1j})!}{d_{1j}!}\cdot ({\boldsymbol{\beta}}_{1(|{\underline{u}}|+d_{1j})}-{\boldsymbol{\beta}}_{w_{j{\underline{u}}}(|{\underline{u}}|+d_{1j})}){\underline{h}}^{\underline{u}}.
          \end{align*}

\begin{align*}
              {\boldsymbol{\gamma}}_{1d_{1j}}({\underline{h}})-{\boldsymbol{\gamma}}_{jd_{1j}}({\underline{h}}) = \sum_{\substack{{\underline{u}}\in \{0,1\}^r,\\ |{\underline{u}}|= d-d_{1j}}} \frac{d!}{d_{1j}!}\cdot ({\boldsymbol{\beta}}_{1d}-{\boldsymbol{\beta}}_{w_{j{\underline{u}}}d}){\underline{h}}^{\underline{u}}.              
          \end{align*}

    We first note that the family $\partial_m{\mathcal Q}$ is normal: The application of the $*$ operation ensures that the polynomials of the family are nonzero and distinct, and the assumption in the proposition ensures that the first polynomial in the family has the highest degree (in $z$).

    We now check that $\partial_m{\mathcal Q}$ satisfies the three properties of a descendent family.
    Since ${\mathcal Q}$ is a descendent family, the polynomials ${\textbf{Q}}_j$ satisfy the formulas \eqref{E: q_j} and \eqref{E: gamma_ji} for some indices $w_{j{\underline{u}}}, w_{\underline{u}}$ with $w_{1{\underline{u}}}=1$.
    Using the binomial theorem, we can expand
    \begin{align*}
        {\textbf{Q}}_j(z+h_{r+1}) &= \sum_{i=0}^d \sum_{\substack{{\underline{u}}\in {\mathbb N}_0^r,\\ |{\underline{u}}|\leq d-i}} {{{u_1+\cdots + u_r+i}\choose{u_1, \ldots, u_r}}}({\boldsymbol{\beta}}_{w_{j{\underline{u}}}(|{\underline{u}}|+i)}-{\boldsymbol{\beta}}_{w_{{\underline{u}}}(|{\underline{u}}|+i)}){\underline{h}}^{\underline{u}} (z+h_{r+1})^i\\
        &=\sum_{i=0}^d \sum_{\substack{{\underline{u}}\in {\mathbb N}_0^r,\\ |{\underline{u}}|\leq d-i}} {{{u_1+\cdots + u_r+i}\choose{u_1, \ldots, u_r}}}({\boldsymbol{\beta}}_{w_{j{\underline{u}}}(|{\underline{u}}|+i)}-{\boldsymbol{\beta}}_{w_{{\underline{u}}}(|{\underline{u}}|+i)}){\underline{h}}^{\underline{u}} \sum_{l=0}^i{{{i}\choose{l}}}h_{r+1}^{i-l}z^l.
    \end{align*}
    Changing the order of summation of $i$ and $l$,  setting $u_{r+1} := i-l$, and using the identity
    \begin{align*}
