        {\textbf{Q}}_j(z+h_{r+1}) = \sum_{l=0}^d z^l \sum_{\substack{({\underline{u}}, u_{r+1})\in {\mathbb N}_0^{r+1},\\ |{\underline{u}}|+u_{r+1}\leq d-l}} {{{u_1+\cdots + u_{r+1}+l}\choose{u_1, \ldots, u_{r+1}}}}\\ ({\boldsymbol{\beta}}_{w_{j{\underline{u}}}(|{\underline{u}}|+u_{r+1}+l)}-{\boldsymbol{\beta}}_{w_{{\underline{u}}}(|{\underline{u}}|+u_{r+1}+l)}){\underline{h}}^{\underline{u}} h_{r+1}^{u_{r+1}}.
    \end{multline*}
    Hence 
    \begin{multline}\label{E: q_j - q_m}
