    \end{multline}
    where we set $w_{j({\underline{u}}, u_{r+1})} := w_{j{\underline{u}}}$ and 
    \begin{align*}
        w_{({\underline{u}}, u_{r+1})} := \begin{cases} w_{\underline{u}},\; &u_{r+1}>0,\\
        w_{m{\underline{u}}},\; &u_{r+1} = 0. 
        \end{cases}
    \end{align*}
  In particular, we have $w_{1({\underline{u}}, u_{r+1})} = w_{1{\underline{u}}}= 1$ by the induction hypothesis, and so $\partial_m {\mathcal Q}$ satisfies property \eqref{i: w_1}.



    To show properties \eqref{i: multilinear} and \eqref{i: leading coeffs},

    we need to compare $\sigma_{h_{r+1}}{{\textbf{Q}}}_1(z,{\underline{h}})-{{\textbf{Q}}}_m(z,{\underline{h}})$ with other polynomials in $\partial_m {\mathcal Q}$ and examine the leading coefficients of these differences (as polynomials in $z$).
   There are three cases to investigate. First, we check \eqref{i: multilinear} and \eqref{i: leading coeffs} for differences of the form
    \begin{multline}\label{E: first case PET}
        (\sigma_{h_{r+1}}{{\textbf{Q}}}_1(z,{\underline{h}})-{{\textbf{Q}}}_m(z,{\underline{h}})) - (\sigma_{h_{r+1}}{{\textbf{Q}}}_j(z,{\underline{h}})-{{\textbf{Q}}}_m(z,{\underline{h}}))\\
        = \sum_{i=1}^{d_{1j}}({\boldsymbol{\gamma}}_{1d_{1j}}({\underline{h}})-{\boldsymbol{\gamma}}_{jd_{1j}}({\underline{h}}))(z+h_{r+1})^i - ({\textbf{Q}}_1(h_{r+1},{\underline{h}}) - {\textbf{Q}}_j(h_{r+1},{\underline{h}})),
    \end{multline}
    where the terms ${{\textbf{Q}}}_m(z,{\underline{h}})$ cancel out.
    The leading coefficient of this expression (interpreted as a polynomial in $z$) is ${\boldsymbol{\gamma}}_{1d_{1j}}({\underline{h}})-{\boldsymbol{\gamma}}_{jd_{1j}}({\underline{h}})$, the same as the leading coefficient of the polynomial ${\textbf{Q}}_1 - {\textbf{Q}}_m$, and this is multilinear by assumption.  For \eqref{i: leading coeffs}, we need to show that the nonzero vectors 
    ${\boldsymbol{\beta}}_{1(|{\underline{u}}|+ u_{r+1}+d_{1j})}-{\boldsymbol{\beta}}_{w_{j({\underline{u}}, u_{r+1})}(|{\underline{u}}|+u_{r+1}+d_{1j})}$ 
    are leading coefficients of the polynomials ${\textbf{P}}_1-{\textbf{P}}_{w_{j({\underline{u}}, u_{r+1})}}$. If $u_{r+1}=0$, then this follows immediately from the formula 
