    \end{align*}
    and the assumption on ${\mathcal Q}$, while if $u_{r+1} = 1$, then 
    \begin{align*}
        {\boldsymbol{\beta}}_{1(|{\underline{u}}|+ u_{r+1}+d_{1j})}-{\boldsymbol{\beta}}_{w_{j({\underline{u}}, u_{r+1})}(|{\underline{u}}|+u_{r+1}+d_{1j})} = {\boldsymbol{\beta}}_{1(|{\underline{u}}|+d_{1j}+1)}-{\boldsymbol{\beta}}_{w_{j{\underline{u}}}(|{\underline{u}}|+d_{1j}+1)}=\mathbf{0}
