    Let $A, \delta>0$, let $s\in{\mathbb N}$,
    let $G$ be a finitely generated abelian group, let $I$ be a finite indexing set, and let $H_i, K_{1i}, \ldots, K_{si}\subseteq G$ be finite multisets for each $i\in I$.  Suppose that $B \subseteq G$ is a set
    satisfying 
    \begin{align*}
        |\mathrm{supp}(B+B-B)|\leq A|B|.
    \end{align*}
Then for all $1$-bounded functions $f$ supported on $B$, the bound
    \begin{align*}
        {\mathbb{E}_{i\in I}\norm{f}_{H_i, K_{1i}, \ldots, K_{si}}^{2^{s+1}}}\geq \delta |B|
    \end{align*}
    implies that
    \begin{align*}
        \mathbb{E}_{i_0, i_1\in I}\norm{f}_{K_{1 i_0}, \ldots, K_{s i_0}, K_{1 i_1}, \ldots, K_{s i_1}, H_{i_1}-H_{i_0}}^{2^{2s+1}}\gg_{A, s} \delta^{2^{2s+1}} |B|.
    \end{align*}

\begin{align*}
        |\mathrm{supp}(B+B-B)|\leq A|B|.
    \end{align*}

\begin{align*}
        {\mathbb{E}_{i\in I}\norm{f}_{H_i, K_{1i}, \ldots, K_{si}}^{2^{s+1}}}\geq \delta |B|
    \end{align*}

\begin{align*}
        \mathbb{E}_{i_0, i_1\in I}\norm{f}_{K_{1 i_0}, \ldots, K_{s i_0}, K_{1 i_1}, \ldots, K_{s i_1}, H_{i_1}-H_{i_0}}^{2^{2s+1}}\gg_{A, s} \delta^{2^{2s+1}} |B|.
    \end{align*}

Let $K_i:=K_{1i}\times \cdots \times K_{si}$.
    The alternative formula \eqref{E: box norms with Fejer kernels} for box norms yields
    \begin{align*}
        \mathbb{E}_{i\in I} \sum_x \sum_{\substack{{\underline{k}} \in K_i}}\sum_{h\in H_i}\mu_{K_i}({\underline{k}}) \mu_{H_i}(h) \Delta_{{\underline{k}}, h}f(x) \geq \delta |B|.
    \end{align*}
    We expand
    \begin{align*}
        \Delta_{{\underline{k}}, h} f(x) = f(x) \overline{f(x+h)} \Delta_{{\underline{k}}}^*\Delta_{h} f(x), 
    \end{align*}
    where $\Delta_{{\underline{k}}}^* f(x) = \prod_{{\underline{\epsilon}}\in\{0,1\}^s\setminus\{0\}}{\mathcal C}^{|{\underline{\epsilon}}|}f(x+{\underline{\epsilon}}\cdot{\underline{k}})$,
    and change 
    the order of summation to get
    \begin{align*}
