\begin{multline*}
        \mathbb{E}_{\substack{h_{lk_1\cdots k_l}\in[\pm H]:\\ k_1, \ldots, k_l\in[t]}}\; \mathbf{1}_{{\mathcal H}}((h_{lk_1\cdots k_l})_{k_1, \ldots, k_l})\cdot \prod_{i_1, \ldots, i_{l-1}\in[\ell]}\;\prod_{j\in[s]}\;\prod_{{\underline{k}}\in{\mathcal K}}\; \prod_{u_{l+1}, \ldots, u_r\in\{0,1\}}  H^{-(u_{l+1}+\cdots + u_r)} M^{-1}\\  \max_{\substack{n\in{\mathbb Z}}}\;
        \mathbb{E}_{\substack{|m_{i_l}|\leq H^{u_{l+1}+\cdots + u_r} M:\\ i_l\in[\ell-1]}} \mathbf{1}\Bigbrac{\sum\limits_{i_l\in[\ell-1]}(h_{lk_{1i_1}\cdots k_{li_l}}- h_{lk_{1i_1}\cdots k_{(l-1)i_{l-1}}k_{l\ell}})m_{i_l} = n},
    \end{multline*}

\begin{multline*}
        H^{-(u_{l+1}+\cdots + u_r)} M^{-1}\frac{\gcd(h_{lk_{1i_1}\cdots k_{(l-1)i_{l-1}}k_{l i_l}}- h_{lk_{1i_1}\cdots k_{(l-1)i_{l-1}}k_{l\ell}}:\; i_l\in[\ell-1])}{\max(h_{lk_{1i_1}\cdots k_{(l-1)i_{l-1}}k_{l i_l}}- h_{lk_{1i_1}\cdots k_{(l-1)i_{l-1}}k_{l\ell}}:\; i_l\in[\ell-1])}
    \end{multline*}

\begin{align*}
        &\ll\mathbb{E}_{\substack{h_{lk_1\cdots k_l}\in[\pm H]:\\ k_1, \ldots, k_l\in[t]}}\; \prod_{i_1, \ldots, i_{l-1}\in[\ell]}\;\prod_{j\in[s]}\;\prod_{{\underline{k}}\in{\mathcal K}}\; \prod_{u_{l+1}, \ldots, u_r\in\{0,1\}}\eta^{-2}M^{-2} H^{-1-2(u_{l+1}+\cdots + u_r)} \\
        &\ll \eta^{-2^{r-l+1}s\ell^{l-1}|{\mathcal K}|}  M^{-2^{r-l+1}s\ell^{l-1}|{\mathcal K}|} H^{-(r-l+1)2^{r-l}s\ell^{l-1}|{\mathcal K}|}.
    \end{align*}

\label{P: systems of multilinear equations}
    Let $\eta>0$, let $\ell, r, s, t\in{\mathbb N}$ with $3\leq\ell\leq t$, and let $H, M\in{\mathbb N}$ with $H\leq M$. Let ${\mathcal K} = {\mathcal K}_{t, \ell, r}$ be as in \eqref{E:set K}, and for each $l\in[r]$, let ${\mathcal H}_l:={\mathcal H}_{l,\eta}$ be as in \eqref{E: H_l}. Then 
        \begin{multline*}
        \max_{\substack{n_{j{\underline{k}}{\underline{u}}}\in{\mathbb Z}:\; j\in[s],\\ {\underline{k}}\in{\mathcal K},\; {\underline{u}}\in\{0,1\}^r}}\;\mathbb{E}_{\substack{m_{j{\underline{k}} i_1\cdots i_r}\in[\pm M]:\\ j\in[s],\; {\underline{k}}\in{\mathcal K},\; i_1, \ldots,  i_r\in[\ell]}}
                \mathbb{E}_{\substack{h_{lk_{1}\cdots k_{l}}\in[\pm H]:\\  k_1, \ldots, k_r\in[t],\; l\in[r]}}\; \Bigbrac{\prod_{l\in[r]}\mathbf{1}_{{\mathcal H}_l}((h_{lk_{1}\cdots k_{l}})_{k_1, \ldots, k_l \in [t]})}\\
        \prod_{j\in[s]}\; \prod_{\substack{{\underline{k}}\in{\mathcal K}}}\prod_{\substack{{\underline{u}}\in\{0,1\}^r
        }} \mathbf{1}\Bigbrac{\sum\limits_{i_1, \ldots, i_r\in[\ell]} h_{1k_{1i_1}}^{u_1} \cdots h_{rk_{1i_1}\cdots k_{ri_r}}^{u_r}m_{j{\underline{k}} i_1\cdots i_r} = n_{j{\underline{k}}{\underline{u}}}}\\
        \ll_{\ell, r, s, t} \eta^{-O_{\ell, r, s,t}(1)}  M^{-2^{r}s|{\mathcal K}|}H^{-r2^{r-1}s|{\mathcal K}|}.
    \end{multline*}
(Here, the superscript $u$'s are exponents, not indices.)

\begin{multline*}
        \max_{\substack{n_{j{\underline{k}}{\underline{u}}}\in{\mathbb Z}:\; j\in[s],\\ {\underline{k}}\in{\mathcal K},\; {\underline{u}}\in\{0,1\}^r}}\;\mathbb{E}_{\substack{m_{j{\underline{k}} i_1\cdots i_r}\in[\pm M]:\\ j\in[s],\; {\underline{k}}\in{\mathcal K},\; i_1, \ldots,  i_r\in[\ell]}}
                \mathbb{E}_{\substack{h_{lk_{1}\cdots k_{l}}\in[\pm H]:\\  k_1, \ldots, k_r\in[t],\; l\in[r]}}\; \Bigbrac{\prod_{l\in[r]}\mathbf{1}_{{\mathcal H}_l}((h_{lk_{1}\cdots k_{l}})_{k_1, \ldots, k_l \in [t]})}\\
        \prod_{j\in[s]}\; \prod_{\substack{{\underline{k}}\in{\mathcal K}}}\prod_{\substack{{\underline{u}}\in\{0,1\}^r
        }} \mathbf{1}\Bigbrac{\sum\limits_{i_1, \ldots, i_r\in[\ell]} h_{1k_{1i_1}}^{u_1} \cdots h_{rk_{1i_1}\cdots k_{ri_r}}^{u_r}m_{j{\underline{k}} i_1\cdots i_r} = n_{j{\underline{k}}{\underline{u}}}}\\
        \ll_{\ell, r, s, t} \eta^{-O_{\ell, r, s,t}(1)}  M^{-2^{r}s|{\mathcal K}|}H^{-r2^{r-1}s|{\mathcal K}|}.
    \end{multline*}

If $s=1$, i.e., we are using Proposition \ref{P: systems of multilinear equations} to concatenate an average of degree-$1$ box norms, then we will always have $t = \ell$, whence $|{\mathcal K}|=1$. Suppose that $t=\ell = 3$ and $r=2$, i.e., we are dealing with a system of equations coming from concatenating an average
\begin{align*}
    \mathbb{E}_{h_1, h_2\in[\pm H]}\norm{f}_{({\boldsymbol{\beta}}_{00} + {\boldsymbol{\beta}}_{10}h_1 + {\boldsymbol{\beta}}_{01}h_2 + {\boldsymbol{\beta}}_{11}h_1h_2)\cdot[\pm M]}^2.
\end{align*}
The resulting system consists of equations of the form
\begin{multline*}
    h_{11}^{u_1}(h_{211}^{u_2}m_{11} + h_{212}^{u_2}m_{12} + h_{213}^{u_2}m_{13}) + h_{12}^{u_1}(h_{221}^{u_2}m_{21} + h_{222}^{u_2}m_{22} + h_{223}^{u_2}m_{23})\\
    + h_{13}^{u_1}(h_{231}^{u_2}m_{31} + h_{232}^{u_2}m_{32} + h_{233}^{u_2}m_{33}) = {n_{u_1 u_2}}
\end{multline*}
for $(u_1, u_2)\in\{0,1\}^2$. Since $n_{u_1 u_2}$ lies in $[\pm 9H^{u_1+u_2}M]$, we expect to get a cancellation on the order of
\begin{align*}
    \ll \prod_{u_1, u_2\in\{0,1\}} H^{-(u_1+u_2)}M^{-1} = H^{-4}M^{-4},
\end{align*}
and modulo the powers of $\eta$, this is indeed what Proposition \ref{P: systems of multilinear equations} gives.

\begin{align*}
        \mathbb{E}_{h_1, h_2\in[\pm H]}\norm{f}_{({\boldsymbol{\beta}}_{00} + {\boldsymbol{\beta}}_{10}h_1 + {\boldsymbol{\beta}}_{01}h_2 + {\boldsymbol{\beta}}_{11}h_1h_2)\cdot[\pm M]}^2.
    \end{align*}

    Suppose now that $r=1$, $s=4$, $t=6$, and $\ell = 4$, so that $|{\mathcal K}| = 15$. Then we have a system of $30$ equations, which we can group into $15$ pairs of equations
    \begin{align*}
    m_{{\underline{k}} 1} + m_{{\underline{k}} 2} +m_{{\underline{k}} 3}+m_{{\underline{k}} 4} = n_{{\underline{k}} 0}\quad \textrm{and}\quad m_{{\underline{k}} 1} h_{k_1} + m_{{\underline{k}} 2} h_{k_2}+m_{{\underline{k}} 3} h_{k_3}+m_{{\underline{k}} 4} h_{k_4} = n_{{\underline{k}} 1}
\end{align*}
corresponding to the $15$ tuples $${\underline{k}}\in{\mathcal K} = \{(k_1, k_2, k_3, k_4):\; 1\leq k_1 < k_2 < k_3 < k_4\leq 6\}.$$ Each $n_{{\underline{k}} 0}$, $n_{{\underline{k}} 1}$ gives cancellation of order $\asymp M^{-1}, \asymp H^{-1} M^{-1}$ (respectively), so the total cancellation will be of order  $\asymp H^{-15}M^{-30}$ (modulo powers of $\eta$, which we ignore here for the simplicity of exposition). We remark that this example does not figure in the proof of Theorem \ref{T: concatenation of polynomials} (but nonetheless is covered by Proposition \ref{P: systems of multilinear equations}).

\begin{align*}
    m_{{\underline{k}} 1} + m_{{\underline{k}} 2} +m_{{\underline{k}} 3}+m_{{\underline{k}} 4} = n_{{\underline{k}} 0}\quad \textrm{and}\quad m_{{\underline{k}} 1} h_{k_1} + m_{{\underline{k}} 2} h_{k_2}+m_{{\underline{k}} 3} h_{k_3}+m_{{\underline{k}} 4} h_{k_4} = n_{{\underline{k}} 1}
\end{align*}

\begin{align}\label{E: cancellation}
\asymp_{r}(H^{-(u_1+\cdots + u_r)} M^{-1}),    
\end{align}

 We let all implicit constants depend on $\ell, r, s, t$. The proof goes by induction on $r$.  The $r=1$ case is the content of Lemma \ref{L: bound on pinned solutions}.  The induction step is in general quite notationally complicated, so, to make it more palatable, we first present the case $r=2$.

\smallskip
\textbf{The case $r=2$.}
\smallskip

In this case, our claimed bound takes the form

        \begin{multline*}
        \max_{\substack{n_{j{\underline{k}}00},\; n_{j{\underline{k}}01},\\ n_{j{\underline{k}}10},\; n_{j{\underline{k}}11}\in{\mathbb Z}:\\ j\in[s],\; {\underline{k}}\in{\mathcal K}}}\;\mathbb{E}_{\substack{m_{j{\underline{k}} i_1 i_2}\in[\pm M]:\\ j\in[s],\; {\underline{k}}\in{\mathcal K},\; i_1, i_2\in[\ell]}}
                \mathbb{E}_{\substack{h_{1k_1}, h_{2k_1k_2}\in[\pm H]:\\ k_1, k_2\in[t]}}\; \mathbf{1}_{{\mathcal H}_1}((h_{1k_1})_{k_1}) \cdot \mathbf{1}_{{\mathcal H}_2}((h_{2k_1k_2})_{k_1, k_2})\\
        \prod_{j\in[s]}\; \prod_{\substack{{\underline{k}}\in{\mathcal K}}}\prod_{\substack{{\underline{u}}\in\{0,1\}^2
        }} \mathbf{1}\Bigbrac{\sum\limits_{i_1, i_2\in[\ell]} h_{1k_{1i_1}}^{u_1} h_{2k_{1i_1}k_{2i_2}}^{u_2}m_{j{\underline{k}} i_1 i_2} = n_{j{\underline{k}}{\underline{u}}}}\\
        \ll \eta^{-O(1)}  M^{-4s|{\mathcal K}|} H^{-4s|{\mathcal K}|}.
    \end{multline*}
    For each $(j,{\underline{k}})\in[s]\times {\mathcal K}$, we have the system of four equations
\begin{align*}
    \sum\limits_{i_1, i_2\in[\ell]} m_{j{\underline{k}} i_1 i_2} &= n_{j{\underline{k}}00}\\
    \sum\limits_{i_1, i_2\in[\ell]} h_{1k_{1i_1}} m_{j{\underline{k}} i_1 i_2} &= n_{j{\underline{k}}10}\\
    \sum\limits_{i_1, i_2\in[\ell]} h_{2k_{1i_1}k_{2i_2}} m_{j{\underline{k}} i_1 i_2} &= n_{j{\underline{k}}01}\\
    \sum\limits_{i_1, i_2\in[\ell]} h_{1k_{1i_1}} h_{2k_{1i_1}k_{2i_2}} m_{j{\underline{k}} i_1 i_2} &= n_{j{\underline{k}}11}.
\end{align*}
This system is quadratic in the $h$ variables, and our goal is to decouple it into two separate systems that are linear in $h$. We accomplish this by introducing two dummy variables
\begin{align*}
    t_{i_1 j {\underline{k}} 0} = \sum_{i_2\in[\ell]}m_{j{\underline{k}} i_1 i_2}\quad \textrm{and}\quad t_{i_1 j {\underline{k}} 1} = \sum_{i_2\in[\ell]}h_{2k_{1i_1}k_{2i_2}} m_{j{\underline{k}} i_1 i_2}
\end{align*}
and renaming $t_{i_1 i_2 j{\underline{k}}} = m_{j{\underline{k}} i_1 i_2}$.  Let us mention the motivation for choosing these variables.  The above system of four equations has three different scales: The first is at scale $\asymp M$, the second and third are at scale $\asymp HM$, and the fourth is at scale $\asymp H^2 M$.  In order to apply the two-scale result from Lemma~\ref{L: bound on pinned solutions}, we want to think of the fourth equation as having scale $\asymp H(HM)$, where the $HM$ here ``matches'' the scale of the third equation.  This is precisely the role played by the second set of dummy variables, which is at scale $\asymp HM$.  The first set of dummy variables, at scale $\asymp M$, pertains to the first and second equations, and the two sets of dummy variables are chosen in such a way that they are related at consecutive scales as in Lemma~\ref{L: bound on pinned solutions}. 

Thus, solving the original system is equivalent to solving
\begin{align*}
    \sum_{i_1\in[\ell]} t_{i_1 j {\underline{k}} 0} = n_{j{\underline{k}}00}\quad \textrm{and}\quad
    \sum_{i_1\in[\ell]} h_{1k_{1i_1}} t_{i_1 j {\underline{k}} 0} = n_{j{\underline{k}}10}\\
    \sum_{i_1\in[\ell]} t_{i_1 j {\underline{k}} 1} = n_{j{\underline{k}}01} \quad \textrm{and}\quad
    \sum_{i_1\in[\ell]} h_{1k_{1i_1}} t_{i_1 j {\underline{k}} 1} = n_{j{\underline{k}}11},
\end{align*}
together with
\begin{align*}
    \sum_{i_2\in[\ell]}t_{i_1 i_2 j{\underline{k}}} = t_{i_1 j {\underline{k}} 0} \quad \textrm{and}\quad
    \sum_{i_2\in[\ell]}h_{2k_{i_1}k_{i_2}}t_{i_1 i_2 j{\underline{k}}} = t_{i_1 j {\underline{k}} 1}\quad \textrm{for\; each}\quad i_1\in[\ell],
\end{align*}
where the variables $t_{i_1 j {\underline{k}} 0}$ and $t_{i_1 j {\underline{k}} 1}$ have ranges $[\pm \ell M]$ and $[\pm\ell H M]$, respectively.  Converting the expectation over the $m$'s to a sum, we see that our normalized count is bounded by $O(M^{-s \ell^2|{\mathcal K}|})$ times 
        \begin{align*}
        &\max_{\substack{n_{j{\underline{k}}00},\; n_{j{\underline{k}}01},\\ n_{j{\underline{k}}10},\; n_{j{\underline{k}}11}\in{\mathbb Z}:\\ j\in[s],\; {\underline{k}}\in{\mathcal K}}}\;
                \mathbb{E}_{\substack{h_{1k_1}\in[\pm H]:\\  k_1\in[t]}}\; \mathbf{1}_{{\mathcal H}_1}((h_{1k_1})_{k_1}) \sum_{\substack{t_{i_1 j{\underline{k}} 0}\in[\pm\ell M],\\ t_{i_1 j{\underline{k}} 1}\in[\pm \ell H M]:\\ j\in[s],\; {\underline{k}}\in{\mathcal K},\; i_1\in[\ell]}}\\
        &\qquad\qquad\qquad\qquad\qquad\qquad\Big(\prod_{j\in[s]}\; \prod_{\substack{{\underline{k}}\in{\mathcal K}}}\prod_{\substack{{\underline{u}}\in\{0,1\}^2}} \mathbf{1}\Bigbrac{\sum\limits_{i_1\in[\ell]} h_{1k_{1i_1}}^{u_1} t_{i_1 j{\underline{k}} u_2} = n_{j{\underline{k}}{\underline{u}}}}\Big)\\
        &\qquad\qquad\qquad\times \Big(\mathbb{E}_{\substack{h_{2k_1k_2}\in[\pm H]:\\  k_1, k_2\in[t]}}\; \mathbf{1}_{{\mathcal H}_2}((h_{2k_1k_2})_{k_1, k_2})
        \sum_{\substack{t_{i_1 i_2 j{\underline{k}}}\in[\pm M]:\\ j\in[s],\; {\underline{k}}\in{\mathcal K},\; i_1, i_2\in[\ell]}}\\
        &\qquad\qquad\qquad\qquad\qquad\qquad\prod_{i_1\in[\ell]}\prod_{j\in[s]}\; \prod_{\substack{{\underline{k}}\in{\mathcal K}}}\prod_{\substack{u_2\in\{0,1\}}} \mathbf{1}\Bigbrac{\sum\limits_{i_2\in[\ell]} h_{2k_{1i_1}k_{2i_2}}^{u_2} t_{i_1 i_2 j{\underline{k}}} = t_{i_1 j{\underline{k}} u_2}}\Big);
    \end{align*}
    we will deal first with the system involving the variables $h_{2k_1k_2}$ and then with the system involving the variables $h_{1k_1}$. Note that
    \begin{align*}
        &\sum_{\substack{t_{i_1 i_2 j{\underline{k}}}\in[\pm M]:\\ j\in[s],\; {\underline{k}}\in{\mathcal K},\; i_1, i_2\in[\ell]}}\prod_{i_1\in[\ell]}\prod_{j\in[s]}\; \prod_{\substack{{\underline{k}}\in{\mathcal K}}}\prod_{\substack{u_2\in\{0,1\}}} \mathbf{1}\Bigbrac{\sum\limits_{i_2\in[\ell]} h_{2k_{1i_1}k_{2i_2}}^{u_2} t_{i_1 i_2 j{\underline{k}}} = t_{i_1 j{\underline{k}} u_2}}\\
        &\qquad=\prod_{i_1\in[\ell]}\prod_{j\in[s]}\; \prod_{\substack{{\underline{k}}\in{\mathcal K}}}\sum_{\substack{t_{i_1 i_2 j{\underline{k}}}\in[\pm M]:\\ i_2\in[\ell]}}\; \mathbf{1}\Bigbrac{\sum\limits_{i_2\in[\ell]} t_{i_1 i_2 j{\underline{k}}} = t_{i_1 j{\underline{k}} 0}}\cdot \mathbf{1}\Bigbrac{\sum\limits_{i_2\in[\ell]} h_{2k_{1i_1}k_{2i_2}} t_{i_1 i_2 j{\underline{k}}} = t_{i_1 j{\underline{k}} 1}}.
    \end{align*}
    Thus, we have
    \begin{align*}
        &\mathbb{E}_{\substack{h_{2k_1k_2}\in[\pm H]:\\  k_1, k_2\in[t]}}\; \mathbf{1}_{{\mathcal H}_2}((h_{2k_1k_2})_{k_1, k_2})
        \sum_{\substack{t_{i_1 i_2 j{\underline{k}}}\in[\pm M],\\ j\in[s],\; {\underline{k}}\in{\mathcal K},\; i_1, i_2\in[\ell]}}\\
        &\qquad\qquad\qquad\qquad\prod_{i_1\in[\ell]}\prod_{j\in[s]}\; \prod_{\substack{{\underline{k}}\in{\mathcal K}}}\prod_{\substack{u_2\in\{0,1\}}} \mathbf{1}\Bigbrac{\sum\limits_{i_2\in[\ell]} h_{2k_{1i_1}k_{2i_2}}^{u_2} t_{i_1 i_2 j{\underline{k}}} = t_{i_1 j{\underline{k}} u_2}}\\
        &\qquad\qquad= \mathbb{E}_{\substack{h_{2k_1k_2}\in[\pm H]:\\  k_1, k_2\in[t]}}\; \mathbf{1}_{{\mathcal H}_2}((h_{2k_1k_2})_{k_1, k_2})\prod_{i_1\in[\ell]}\prod_{j\in[s]}\; \prod_{\substack{{\underline{k}}\in{\mathcal K}}}\\ 
        &\qquad\qquad\qquad\qquad\sum_{\substack{t_{i_1 i_2 j{\underline{k}}}\in[\pm M]:\\ i_2\in[\ell]}}\; \mathbf{1}\Bigbrac{\sum\limits_{i_2\in[\ell]} t_{i_1 i_2 j{\underline{k}}} = t_{i_1 j{\underline{k}} 0}}\cdot \mathbf{1}\Bigbrac{\sum\limits_{i_2\in[\ell]} h_{2k_{1i_1}k_{2i_2}} t_{i_1 i_2 j{\underline{k}}} = t_{i_1 j{\underline{k}} 1}}.
    \end{align*}
    Lemma \ref{L: bound on pinned solutions} applied with $l=r=2$ allows us to bound this expression by 
    $$O(\eta^{-O(1)} M^{s\ell^2|{\mathcal K}|-2s\ell|{\mathcal K}|} H^{-s\ell|{\mathcal K}|}).$$
    Similarly, the count of solutions to the system involving the variables $h_{1k_1}$ is
\begin{align*}
        &\max_{\substack{n_{j{\underline{k}}00},\; n_{j{\underline{k}}01},\\ n_{j{\underline{k}}10},\; n_{j{\underline{k}}11}\in{\mathbb Z}:\\ j\in[s],\; {\underline{k}}\in{\mathcal K}}}\;
        \mathbb{E}_{\substack{h_{1k_1}\in[\pm H]:\\  k_1\in[t]}}\; \mathbf{1}_{{\mathcal H}_1}((h_{1k_1})_{k_1}) \sum_{\substack{t_{i_1 j{\underline{k}} 0}\in[\pm\ell M],\\ t_{i_1 j{\underline{k}} 1}\in[\pm\ell H M]:\\ j\in[s],\; {\underline{k}}\in{\mathcal K},\; i_1\in[\ell]}}\\
        &\qquad\qquad\qquad\prod_{j\in[s]}\; \prod_{\substack{{\underline{k}}\in{\mathcal K}}}\prod_{\substack{{\underline{u}}\in\{0,1\}^2}} \mathbf{1}\Bigbrac{\sum\limits_{i_1\in[\ell]} h_{1k_{1i_1}}^{u_1} t_{i_1 j{\underline{k}} u_2} = n_{j{\underline{k}}{\underline{u}}}}\\
        &\qquad\leq  \mathbb{E}_{\substack{h_{1k_1}\in[\pm H]:\\  k_1\in[t]}}\; \mathbf{1}_{{\mathcal H}_1}((h_{1k_1})_{k_1}) \prod_{j\in[s]}\; \prod_{\substack{{\underline{k}}\in{\mathcal K}}}\prod_{\substack{u_2\in\{0,1\}}}\\
        &\qquad\qquad\qquad\max_{n_0, n_1\in{\mathbb Z}}\; \sum_{\substack{t_{i_1 j{\underline{k}} u_2}\in[\pm\ell H^{u_2} M]:\\  i_1\in[\ell]}}\mathbf{1}\Bigbrac{\sum\limits_{i_1\in[\ell]} t_{i_1 j{\underline{k}} u_2} = n_0}\cdot \mathbf{1}\Bigbrac{\sum\limits_{i_1\in[\ell]} h_{1k_{1i_1}} t_{i_1 j{\underline{k}} u_2} = n_1},
\end{align*}
and this can be bounded by
$$O(\eta^{-O(1)} M^{2 s\ell |{\mathcal K}|-4s|{\mathcal K}|} H^{s\ell|{\mathcal K}|-4s|{\mathcal K}|})$$
using the case $l=1, r=2$ of Lemma \ref{L: bound on pinned solutions}. Note that the big centered equations had an  \emph{inequality} rather than an \emph{equality} because we interchanged the $\max$ with the sums and products.

    Combining these two bounds and the normalising factor $O(M^{-s \ell^2|{\mathcal K}|})$, we bound the overall normalised count by
    \begin{align*}
        &\ll M^{-s \ell^2|{\mathcal K}|}\cdot \brac{\eta^{-O(1)} M^{s\ell^2|{\mathcal K}|-2s\ell|{\mathcal K}|} H^{-s\ell|{\mathcal K}|}}\cdot \brac{\eta^{-O(1)} M^{2 s\ell|{\mathcal K}|-4s|{\mathcal K}|} H^{s\ell|{\mathcal K}|-4s|{\mathcal K}|}}\\
        &= \eta^{-O(1)} M^{-4s|{\mathcal K}|}H^{-4s|{\mathcal K}|},
    \end{align*}
    as claimed.

\smallskip
\textbf{The case $r>2$.}
\smallskip

We handle the case $r>2$ similarly. For $l\in[r]$, $i_1, \ldots, i_l\in[\ell]$, $j\in[s]$, ${\underline{k}}\in{\mathcal K}$, ${\underline{u}}\in\{0,1\}^r$, we define the auxiliary variable
\begin{align*}
    t_{i_1\cdots i_l j {\underline{k}}{\underline{u}}} =\sum\limits_{i_{l+1}, \ldots, i_r\in[\ell]}h_{(l+1)k_{1i_1} \cdots k_{(l+1)i_{l+1}}}^{u_{l+1}}\cdots h_{r k_{1i_1}\cdots k_{ri_r}}^{u_r}m_{j{\underline{k}} i_1\cdots i_r}
\end{align*}
at scale $H^{u_{l+1}+\cdots+u_r}M$.
Notice that $t_{i_1\cdots i_l j {\underline{k}}{\underline{u}}}$ depends on only the coordinates $u_{l+1}, \ldots, u_r$ of ${\underline{u}}$ and that the $t$'s satisfy the relation
\begin{align}\label{E: recurrence relation on t}
    t_{i_1\cdots i_l j {\underline{k}}{\underline{u}}} = \sum_{i_{l+1}\in[\ell]}h_{(l+1)k_{1i_1} \cdots k_{(l+1)i_{l+1}}}^{u_{l+1}} t_{i_1\cdots i_{l+1} j {\underline{k}}{\underline{u}}}.
\end{align}
Iterating \eqref{E: recurrence relation on t} through intermediate scales, we see that {for each $j \in [s]$ and ${\underline{k}} \in {\mathcal K}$,} we can rewrite
\begin{align*}
        &\sum_{\substack{m_{j{\underline{k}} i_1\cdots i_r}\in[\pm M]:\\ 

        i_1, \ldots,  i_r\in[\ell]}} \mathbf{1}\Bigbrac{\sum\limits_{i_1, \ldots, i_r\in[\ell]} h_{1k_{1i_1}}^{u_1} \cdots h_{rk_{1i_1}\cdots k_{ri_r}}^{u_r}m_{j{\underline{k}} i_1\cdots i_r} = n_{j{\underline{k}}{\underline{u}}}} \\
        &\qquad\qquad\qquad=\sum_{\substack{|t_{i_1 j{\underline{k}}{\underline{u}}}|\ll H^{u_2+\cdots + u_r}M:\\ i_1\in[\ell]}} \mathbf{1}\Bigbrac{\sum\limits_{i_1\in[\ell]} h_{1k_{1i_1}}^{u_1} t_{i_1 j{\underline{k}}{\underline{u}}}= n_{j{\underline{k}}{\underline{u}}}}\\ 
    &\qquad\qquad\qquad\times \sum_{\substack{|t_{i_1i_2 j{\underline{k}}{\underline{u}}}|\ll H^{u_3+\cdots +u_r}M:\\ i_1, i_2\in[\ell]}}\;\prod_{i_1\in[\ell]} \mathbf{1}\Bigbrac{\sum\limits_{i_2\in[\ell]} h_{2k_{1i_1}k_{2i_2}}^{u_2}t_{i_1 i_2 j{\underline{k}}{\underline{u}}} = t_{i_1 j{\underline{k}}{\underline{u}}}}\\
